<?php require_once __DIR__.'/includes/db.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $q=$pdo->prepare('SELECT * FROM pertandingan WHERE id=?'); $q->execute([$id?:0]); $match=$q->fetch(); if(!$match){http_response_code(404);} $q=$pdo->prepare('SELECT * FROM kategori_tiket WHERE pertandingan_id=? AND stok>0 ORDER BY harga'); $q->execute([$match['id']??0]); $categories=$q->fetchAll(); ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Pertandingan | LagaKita</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><main class="container py-5"><?php if(!$match): ?><h1>Pertandingan tidak ditemukan</h1><a href="pertandingan.php">Kembali ke jadwal</a><?php else: ?><a href="pertandingan.php" class="text-muted">← Semua pertandingan</a><div class="row g-5 mt-1"><div class="col-lg-7"><p class="eyebrow"><?= e($match['kompetisi']) ?></p><h1 class="display-5 fw-bold"><?= e($match['tim_tuan_rumah']) ?> <span class="text-muted">vs</span> <?= e($match['tim_tamu']) ?></h1><p class="lead mt-4"><?= e(date('l, d F Y · H:i',strtotime($match['tanggal']))) ?> WIB</p><p class="text-muted"><?= e($match['stadion']) ?> · <?= e($match['kota']) ?></p><p><?= nl2br(e($match['deskripsi'])) ?></p></div><div class="col-lg-5"><div class="card match-card"><div class="card-body p-4"><h2 class="h4 fw-bold mb-3">Pilih kategori tiket</h2><?php foreach($categories as $cat): ?><div class="d-flex justify-content-between border-bottom py-3"><div><strong><?= e($cat['nama_kategori']) ?></strong><div class="small text-muted">Sisa <?= (int)$cat['stok'] ?></div></div><strong><?= rupiah($cat['harga']) ?></strong></div><?php endforeach; ?><?php if($categories): ?><a class="btn btn-success w-100 mt-4" href="pesan.php?id=<?= (int)$match['id'] ?>">Pesan tiket</a><?php else: ?><p class="text-muted mt-3 mb-0">Tiket sedang habis atau belum tersedia.</p><?php endif; ?></div></div></div></div><?php endif; ?></main><?php include __DIR__.'/includes/footer.php'; ?></body></html>
